using UnityEngine;using StarterAssets;using System.Collections.Generic;
namespace WildernessCombat {
public sealed class WildernessEnemy:MonoBehaviour,ICombatDamageReceiver {
 static readonly float[] ComboWindows={.22f,.46f,.67f};
 enum Mode{Patrol,Chase,Attack,Recover,Hurt,Dead}
 public bool Cyclops{get;private set;}public bool Mage{get;private set;}public float Health{get;private set;}public bool IsDamageable=>initialized&&state!=Mode.Dead;public Transform DamageRoot=>transform;public Vector3 Home=>home;
 WildernessEnemyWorld world;WildernessEnemySettings settings;WildernessEnemyAnimation animationPlayer;WildernessFlightPose flightPose;CharacterController controller;Transform visual,leftHand;GameObject blade;Mode state;Vector3 home,patrol,lockedAim,push;float timer,age,phase,cooldown,respawnAt;bool fired,initialized;AnimationClip idle,activeAttack;float maxHealth;int strikeCount;bool heavy;readonly List<Transform> wings=new List<Transform>();readonly List<Quaternion> wingRest=new List<Quaternion>();
 public void Initialize(WildernessEnemyWorld owner,GameObject prefab,bool mage,Vector3 point,float randomPhase,bool cyclops=false){Cyclops=cyclops;world=owner;settings=owner.Settings;Mage=mage;home=point;phase=randomPhase;patrol=home;maxHealth=Cyclops?420:settings.Health;Health=maxHealth;idle=Cyclops?settings.CyclopsIdle:settings.Hover;activeAttack=Cyclops?settings.CyclopsSwing:settings.Attack;
 visual=Instantiate(prefab,transform).transform;visual.name="Flying fairy visual";var animator=visual.GetComponentInChildren<Animator>();animationPlayer=gameObject.AddComponent<WildernessEnemyAnimation>();animationPlayer.Initialize(animator);flightPose=gameObject.AddComponent<WildernessFlightPose>();flightPose.Initialize(visual,animator);leftHand=animator.GetBoneTransform(HumanBodyBones.LeftHand);
 foreach(var t in visual.GetComponentsInChildren<Transform>())if(t.name.Contains("Wing")){wings.Add(t);wingRest.Add(t.localRotation);}
 controller=gameObject.AddComponent<CharacterController>();controller.height=Cyclops?settings.CyclopsHeight-.05f:1.65f;controller.radius=Cyclops?settings.CyclopsHeight*.205f:.29f;controller.center=Vector3.up*(Cyclops?settings.CyclopsHeight*.5f:.85f);controller.stepOffset=.1f;controller.slopeLimit=55;
 if(Cyclops){CyclopsSizing.FitHeight(visual.gameObject,settings.CyclopsHeight);controller.enabled=false;transform.position=home+Vector3.up*.04f;controller.enabled=true;if(settings.CyclopsClub&&leftHand){CyclopsSizing.AttachClub(settings,visual,leftHand);}}else if(!mage)MakeSword();initialized=true;state=Mode.Patrol;animationPlayer.Play(idle,true,1.05f);cooldown=.5f+phase*.1f;}
 void MakeSword(){if(!leftHand)return;blade=new GameObject("Left-hand basic sword");blade.transform.SetParent(leftHand,false);blade.transform.localPosition=new Vector3(0,.035f,0);
 MakePart("Blade",new Vector3(0,0,.43f),new Vector3(.045f,.015f,.75f));MakePart("Guard",new Vector3(0,0,.02f),new Vector3(.20f,.035f,.035f));MakePart("Handle",new Vector3(0,0,-.09f),new Vector3(.035f,.035f,.18f));}
 void MakePart(string name,Vector3 position,Vector3 scale){var part=GameObject.CreatePrimitive(PrimitiveType.Cube);part.name=name;part.transform.SetParent(blade.transform,false);part.transform.localPosition=position;part.transform.localScale=scale;part.GetComponent<Renderer>().sharedMaterial=settings.SwordMaterial;Destroy(part.GetComponent<Collider>());}
 void Update(){if(!initialized||!world||!world.Player)return;float dt=Time.deltaTime;age+=dt;cooldown-=dt;
 if(state==Mode.Dead){timer+=dt;if(timer>1.05f&&visual.gameObject.activeSelf){visual.gameObject.SetActive(false);animationPlayer.enabled=false;}if(Time.time>respawnAt&&Vector3.Distance(world.Player.position,home)>28&&!world.PlayerSafe){controller.enabled=false;transform.position=home+Vector3.up*(Cyclops?.04f:.55f);controller.enabled=true;visual.gameObject.SetActive(true);animationPlayer.enabled=true;maxHealth=Cyclops?420:settings.Health;Health=maxHealth;idle=Cyclops?settings.CyclopsIdle:settings.Hover;activeAttack=Cyclops?settings.CyclopsSwing:settings.Attack;state=Mode.Patrol;timer=0;animationPlayer.Play(idle,true,1.05f);}return;}
 bool distant=(world.Player.position-transform.position).sqrMagnitude>8100f;
 if(animationPlayer.enabled==distant)animationPlayer.enabled=!distant;
 if(distant){world.EndAttack(this);if(state==Mode.Attack||state==Mode.Hurt||state==Mode.Recover){state=Mode.Patrol;animationPlayer.Play(idle,true,1.05f);}return;}
 if(DomainInteractionState.IsModal)return;
 if(state==Mode.Hurt){timer-=dt;Move(push,dt);push=Vector3.MoveTowards(push,Vector3.zero,dt*12);if(timer<=0){state=Mode.Recover;timer=.12f;}return;}
 bool near=!world.PlayerSafe&&Vector3.Distance(world.Player.position,home)<settings.LeashDistance&&Vector3.Distance(world.Player.position,transform.position)<settings.AggroDistance;
 if(state==Mode.Attack){timer+=dt;float duration=activeAttack.length/(Cyclops?1.3f:1.6f);if(heavy){if(strikeCount<3&&timer>=duration*ComboWindows[strikeCount]){strikeCount++;Strike();}}else if(!fired&&timer>=duration*.4f){fired=true;Strike();}if(!Mage&&timer<duration*.45f)Move(Vector3.ProjectOnPlane(lockedAim-transform.position,Vector3.up).normalized*2.2f,dt);if(timer>=duration*.77f){world.EndAttack(this);state=Mode.Recover;timer=.3f;animationPlayer.Play(idle,true,1.05f);}return;}
 if(state==Mode.Recover){timer-=dt;Move(Vector3.zero,dt);if(timer<=0)state=near?Mode.Chase:Mode.Patrol;return;}
 if(near){state=Mode.Chase;Vector3 target=world.Player.position;float distance=Vector3.ProjectOnPlane(target-transform.position,Vector3.up).magnitude;Face(target,dt);
 float range=Mage?10f:Cyclops?settings.CyclopsHeight*.95f:2.1f;Vector3 desired=Mage&&distance<5 ? (transform.position-target).normalized*4 : distance>range*.85f ? (target-transform.position).normalized*(Cyclops?6f:settings.MoveSpeed) : Vector3.zero;Move(desired,dt);
 if(distance<range&&cooldown<=0&&world.ClearLine(transform.position+Vector3.up,world.Player.position+Vector3.up*.9f,transform)&&world.BeginAttack(this)){lockedAim=world.Player.position+Vector3.up*.9f;state=Mode.Attack;timer=0;fired=false;cooldown=1.3f+Mathf.Sin(phase)*.15f;heavy=Cyclops&&settings.CyclopsCombo&&Random.value<.25f;strikeCount=0;activeAttack=heavy?settings.CyclopsCombo:Cyclops?(Random.value<.5f&&settings.CyclopsScratch?settings.CyclopsScratch:settings.CyclopsSwing):settings.Attack;animationPlayer.Play(activeAttack,false,Cyclops?1.3f:1.6f);} }
 else{state=Mode.Patrol;if(Vector3.Distance(transform.position,home)>5)patrol=home;else if(Vector3.ProjectOnPlane(patrol-transform.position,Vector3.up).magnitude<.8f)patrol=home+new Vector3(Mathf.Sin(age*.4f+phase),0,Mathf.Cos(age*.4f+phase))*3;Face(patrol,dt);Move((patrol-transform.position).normalized*2f,dt);}}
 void Face(Vector3 point,float dt){Vector3 d=point-transform.position;d.y=0;if(d.sqrMagnitude>.02f)transform.rotation=Quaternion.RotateTowards(transform.rotation,Quaternion.LookRotation(d),720*dt);}
 void Move(Vector3 velocity,float dt){if(!controller.enabled)return;velocity.y=0;velocity+=world.Separation(this);Vector3 next=transform.position+velocity*dt;if(!world.IsWild(next)){velocity=Vector3.ProjectOnPlane(home-transform.position,Vector3.up).normalized*4;next=transform.position+velocity*dt;}
 float ground=world.Ground(next);float hover=Cyclops?.04f:state==Mode.Attack&&!Mage?.20f:.55f;float y=ground+hover+Mathf.Sin(age*2.3f+phase)*(Cyclops?0:.08f);velocity.y=Mathf.Clamp((y-transform.position.y)*8,-8,5);Vector3 before=transform.position;controller.Move(velocity*dt);if(Cyclops&&(state==Mode.Patrol||state==Mode.Chase)){float speed=Vector3.ProjectOnPlane(transform.position-before,Vector3.up).magnitude/Mathf.Max(.001f,dt);animationPlayer.Play(speed>.2f?settings.CyclopsWalk:idle,true,speed>3?2.2f:1.1f);}}
 void Strike(){if(world.PlayerSafe)return;var sound=GetComponent<CombatSoundEmitter>();if(!sound)sound=gameObject.AddComponent<CombatSoundEmitter>();sound.EnemyAttack(Cyclops);if(Mage){Vector3 origin=leftHand?leftHand.position:transform.position+Vector3.up*1.2f;WildernessMagicBolt.Fire(world,this,origin,lockedAim,settings.AttackDamage,settings.MagicMaterial);}else{Vector3 delta=world.Player.position-transform.position;if(Vector3.ProjectOnPlane(delta,Vector3.up).magnitude<(Cyclops?settings.CyclopsHeight*1.1f:2.6f)&&Mathf.Abs(delta.y)<(Cyclops?2.3f:2)&&Vector3.Dot(transform.forward,Vector3.ProjectOnPlane(delta,Vector3.up).normalized)>.3f&&world.ClearLine(transform.position+Vector3.up,world.Player.position+Vector3.up,transform))world.HurtPlayer(Cyclops?(heavy?20:30):settings.AttackDamage+3,transform.position);}}
 public void ReceiveDamage(float damage,Transform attacker){if(!IsDamageable||damage<=0)return;Health=Mathf.Max(0,Health-damage);world.EndAttack(this);push=attacker?Vector3.ProjectOnPlane(transform.position-attacker.position,Vector3.up).normalized*(damage>=45?6:2):Vector3.zero;
 if(Health<=0){flightPose.Evaluate(false,!Mage,phase,Time.deltaTime);state=Mode.Dead;timer=0;respawnAt=Time.time+settings.RespawnSeconds;controller.enabled=false;animationPlayer.Play(settings.Knockback,false,1.1f);}else{state=Mode.Hurt;timer=damage>=45?.5f:.23f;animationPlayer.Play(damage>=45?settings.Knockback:settings.Hit,false,1.2f);cooldown=.5f;}}
 void LateUpdate(){if(!initialized||state==Mode.Dead||!animationPlayer.enabled)return;bool locomotion=!Cyclops&&(state==Mode.Patrol||state==Mode.Chase)&&!DomainInteractionState.IsModal;flightPose.Evaluate(locomotion,!Mage,phase,Time.deltaTime);float flight=flightPose.MovementBlend;for(int i=0;i<wings.Count;i++)wings[i].localRotation=wingRest[i]*Quaternion.AngleAxis(Mathf.Sin(age*(12+flight*9)+phase)*(i%2==0?1:-1)*(10+flight*12),Vector3.up);}
 void OnDisable(){if(world)world.EndAttack(this);}
 void OnGUI(){if(!initialized||!IsDamageable||!world||!world.Player||!Camera.main||Vector3.Distance(world.Player.position,transform.position)>18||Health>=maxHealth&&state==Mode.Patrol)return;var p=Camera.main.WorldToScreenPoint(transform.position+Vector3.up*(Cyclops?settings.CyclopsHeight+.3f:2.05f));if(p.z<=0)return;float x=p.x-48,y=Screen.height-p.y;Color old=GUI.color;GUI.color=new Color(.06f,.07f,.08f,.85f);GUI.DrawTexture(new Rect(x,y,96,6),Texture2D.whiteTexture);GUI.color=Mage?new Color(.5f,.6f,1):new Color(1,.45f,.3f);GUI.DrawTexture(new Rect(x,y,96*Mathf.Clamp01(Health/maxHealth),6),Texture2D.whiteTexture);GUI.color=old;}
}}

